properties.property:
local BlockPlayer = require "actions/BlockPlayer"
local Do = require "actions/Do"
local Ease = require "actions/Ease"
local PlayAudio = require "actions/PlayAudio"
local Wait = require "actions/Wait"
local Parallel = require "actions/Parallel"
local Serial = require "actions/Serial"

return function(self)
    return BlockPlayer {
        Do(function()
            self.scene.objectLookup.Cheetah2.hidden = false
            self.scene.objectLookup.Cheetah2.sprite:setAnimation("runright")
        end),
        Parallel {
            Do(function() self.scene.objectLookup.Cheetah2.x = self.scene.player.x - 1000 end),
            Serial {
                Ease(self.scene.camPos, "x", 600, 0.5),
                PlayAudio("sfx", "cheetabreathe", 1, true),
                Wait(2),
                Do(function()
                    scene.player.sprite:popOverride("juiceright")
                    scene.player.sprite:pushOverride("juiceright", "juicescaredright2")
                end),
                Ease(self.scene.camPos, "x", 0, 0.5),
            }
        },
        Do(function()
            self.scene.objectLookup.Cheetah2.hidden = true
        end)
    }
end
